// The WhatsApp Trigger outputs the 'value' object of Meta's webhook.
const value = $input.first().json;
// Turn a WhatsApp message into the fields the rest of the flow needs.
const m = value.messages?.[0];
if (!m) return []; // delivery/read receipts carry no message: nothing to do
const contact = value.contacts?.[0] || {};
// Screenshots usually arrive as an image; some people send them as a document
const media = m.image || (m.document?.mime_type?.startsWith('image/') ? m.document : null);
const ts = Number(m.timestamp) || Math.floor(Date.now() / 1000);
return [{ json: {
  from: m.from,
  senderName: contact.profile?.name || '',
  messageId: m.id,
  receivedAt: DateTime.fromSeconds(ts).setZone('Asia/Kolkata').toFormat('yyyy-MM-dd HH:mm:ss'),
  hasImage: !!media,
  mediaId: media?.id || '',
  mimeType: media?.mime_type || 'image/jpeg',
  caption: media?.caption || m.text?.body || '',
  imageBase64: media?.mock_base64 || '' // mock only: the real flow downloads the image from WhatsApp
} }];

// Turn the downloaded screenshot into base64 for Claude
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const msg = $('Read WhatsApp Message').first().json;
const mimeType = ($input.first().binary.data.mimeType || msg.mimeType).split(';')[0];
return [{ json: { ...msg, mimeType, imageBase64: buffer.toString('base64') } }];

// Reads Claude's JSON and shapes the spreadsheet row and the WhatsApp reply.
// Optional: words that must appear in the payee name or UPI ID, e.g. ['sunrise']. Leave [] to accept any payee.
const EXPECTED_PAYEE = [];

const msg = $('Attach Image Data').first().json;
const text = $input.first().json.content?.[0]?.text || '';
let x = null;
try {
  const json = text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1);
  x = JSON.parse(json);
} catch (e) { x = null; }

const has = v => v !== undefined && v !== null && String(v).trim() !== '';
const digits = v => String(v || '').replace(/\D/g, '').replace(/^(91|0)(?=\d{10}$)/, '');
const sender = digits(msg.from);

// Claude unreachable or unreadable answer: still log it so nothing is lost
const unread = !x;
if (unread) x = { is_payment_screenshot: true, confidence: 'low' };
if (x.is_payment_screenshot === false) {
  return [{ json: { isPayment: false, from: msg.from, reason: x.issues || '' } }];
}

const mobile = digits(x.payer_mobile);
const amount = has(x.amount) ? Number(String(x.amount).replace(/[^\d.]/g, '')) : null;
const status = x.payment_status || 'Unknown';
const payee = [x.payee_name, x.payee_upi_id].filter(has).join(' ');

const review = [];
if (unread) review.push('could not read the screenshot automatically');
else if (status !== 'Success') review.push(`payment ${status.toLowerCase()}`);
if (!unread && !amount) review.push('amount missing');
if (!unread && !has(x.transaction_id)) review.push('txn ID missing');
if (!unread && x.confidence === 'low') review.push('low confidence');
if (EXPECTED_PAYEE.length && !EXPECTED_PAYEE.some(w => payee.toLowerCase().includes(w.toLowerCase()))) review.push('paid to someone else');
if (has(x.issues) && x.confidence !== 'high') review.push(x.issues);

const comments = [
  has(x.note_in_screenshot) && `Note: ${x.note_in_screenshot}`,
  has(msg.caption) && `Message: ${msg.caption}`,
  has(x.other_reference) && `Other ref: ${x.other_reference}`
].filter(Boolean).join(' | ');

const row = {
  'Received At': msg.receivedAt,
  'Sender WhatsApp': sender,
  'Sender Name': msg.senderName,
  'Mobile Number': mobile.length === 10 ? mobile : sender,
  'Payer Name': x.payer_name || '',
  'Amount': amount ?? '',
  'Txn ID': x.transaction_id ? String(x.transaction_id).replace(/\s/g, '') : '',
  'Payment Date': x.payment_date || '',
  'Payment Time': x.payment_time || '',
  'Payment App': x.payment_app || '',
  'Payment Status': status,
  'Paid To': payee,
  'Comments': comments,
  'Review Status': review.length ? `Needs review: ${review.join(', ')}` : 'OK',
  'Confidence': x.confidence || '',
  'WhatsApp Message ID': msg.messageId
};
return [{ json: { isPayment: true, from: msg.from, row } }];

// Marks the row as a duplicate if the same Txn ID is already in the sheet, then outputs just the row to append.
const { row } = $('Parse Payment Details').first().json;
const logged = $input.all().map(i => i.json).filter(r => r && r['Txn ID']);
const earlier = row['Txn ID'] && logged.find(r => String(r['Txn ID']) === String(row['Txn ID']));
if (earlier) row['Review Status'] = `Duplicate of payment logged at ${earlier['Received At']}`;
return [{ json: row }];

// Writes the confirmation sent back to the customer
const r = $('Check Duplicate').first().json;
const amt = r['Amount'] !== '' ? `₹${Number(r['Amount']).toLocaleString('en-IN')}` : 'your payment';
const when = r['Payment Date'] ? ` on ${DateTime.fromISO(r['Payment Date']).toFormat('d LLL yyyy')}` : '';
const txn = r['Txn ID'] ? ` (Txn ID ${r['Txn ID']})` : '';
let replyText;
if (r['Review Status'].startsWith('Duplicate')) replyText = `This payment${txn} is already recorded. No need to send it again. 🙏`;
else if (r['Review Status'] === 'OK') replyText = `✅ Received ${amt}${when}${txn} via ${r['Payment App'] || 'UPI'}. Thank you!`;
else replyText = `Thanks, we got your screenshot for ${amt}${txn}. Our team will verify it and confirm shortly.`;
return [{ json: { from: $('Parse Payment Details').first().json.from, replyText, row: r } }];
